def fill_refunded(apps, schema_editor):
    """
    Старые закрытые заказы (отменён / отклонён / заблокирован): refunded = сколько РЕАЛЬНО
    вернули по старой формуле. Тогда «потерянное» старой формулой видно как остаток,
    и его можно вернуть командой legacy_refund_report --apply.

    Старая формула (_refund_unspent до этапа 2): не было показов — весь бюджет;
    иначе неистраченные показы × SPM / 1000, округлено вниз до копеек.
    Неистраченные показы = total_views − shown_views (remaining_views старый возврат обнулил).
    """
    ChatAdOrder = apps.get_model('chat_ads', 'ChatAdOrder')
    closed = ChatAdOrder.objects.filter(Q(cancelled=True) | Q(status__in=['REJECTED', 'BLOCKED']))
    for order in closed.iterator():
        if order.shown_views == 0:
            refunded = order.budget
        else:
            unspent_views = max(order.total_views - order.shown_views, 0)
            refunded = (Decimal(unspent_views) / Decimal(1000) * order.spm).quantize(
                Decimal('0.01'), rounding=ROUND_DOWN)
        ChatAdOrder.objects.filter(pk=order.pk).update(refunded=refunded)


